import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/theme.dart';
import 'session_controller.dart';
import 'add_user_screen.dart';
class UserManagementScreen extends StatefulWidget{const UserManagementScreen({super.key,required this.session});final SessionController session;@override State<UserManagementScreen> createState()=>_UserManagementScreenState();}
class _UserManagementScreenState extends State<UserManagementScreen>{List<dynamic> users=[];String? error;bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);try{final d=await widget.session.users();if(mounted)setState(()=>users=d['users'] as List<dynamic>? ?? []);}on ApiException catch(e){if(mounted)setState(()=>error=e.message);}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){final count=(String role)=>users.where((u)=>u['role']==role).length;return Scaffold(backgroundColor:const Color(0xFFF5F8FC),appBar:AppBar(backgroundColor:const Color(0xFFF5F8FC),title:const Text('User management',style:TextStyle(color:Color(0xFF0F2440),fontWeight:FontWeight.w800))),floatingActionButton:FloatingActionButton(backgroundColor:HRMateTheme.blue,onPressed:() async { final created=await Navigator.of(context).push<bool>(MaterialPageRoute(builder:(_)=>AddUserScreen(session:widget.session))); if(created==true)load(); },child:const Icon(Icons.person_add)),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(20),children:[Wrap(spacing:8,runSpacing:8,children:[_role('Super admins',count('super_admin')),_role('HR managers',count('hr_manager')),_role('Supervisors',count('supervisor')),_role('Employees',count('employee'))]),const SizedBox(height:18),TextField(decoration:InputDecoration(hintText:'Search users',prefixIcon:const Icon(Icons.search),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(15),borderSide:BorderSide.none))),const SizedBox(height:12),if(loading)const Padding(padding:EdgeInsets.all(50),child:Center(child:CircularProgressIndicator()))else if(error!=null)Text(error!)else for(final u in users)_user(u as Map<String,dynamic>)])));}Widget _role(String label,int n)=>SizedBox(width:160,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$n',style:const TextStyle(color:HRMateTheme.blue,fontSize:22,fontWeight:FontWeight.w900)),Text(label,style:const TextStyle(fontSize:11))]))));Widget _user(Map<String,dynamic> u)=>Card(child:ListTile(leading:CircleAvatar(child:Text((u['name']??'U').toString().substring(0,1))),title:Text(u['name']??''),subtitle:Text(u['phone']??''),trailing:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Chip(label:Text((u['role']??'').toString().replaceAll('_',' '),style:const TextStyle(fontSize:9))),const Text('● Active',style:TextStyle(color:HRMateTheme.green,fontSize:10))])));}
